import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Alcance de armas y distancia","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/reach-and-spacing.md","filePath":"es/game-design/combat/reach-and-spacing.md"}'),c={name:"es/game-design/combat/reach-and-spacing.md"};function s(r,e,o,d,l,m){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="weapon-reach-and-spacing" tabindex="-1">Alcance de armas y distancia <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Enlace permanente a &quot;Alcance de armas y distancia&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Los ejemplos numéricos son hipótesis de prototipo, no equilibrio definitivo. <strong>Implementación/disponibilidad:</strong> no establecida para estas mecánicas. <strong>Verificación:</strong> revisión documental, sin prototipo jugable. <strong>Revisión:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a></p><h2 id="reach-belongs-to-all-weapons" tabindex="-1">Todas las armas tienen alcance <a class="header-anchor" href="#reach-belongs-to-all-weapons" aria-label="Enlace permanente a &quot;Todas las armas tienen alcance&quot;">​</a></h2><p>A distancia no significa solo arcos. El alcance es el máximo físico de una acción; distancia mínima/efectiva y huella espacial son conceptos distintos. Un arma larga puede destacar a distancia y manejarse mal de cerca.</p><table tabindex="0"><thead><tr><th>Arma/acción ilustrativa</th><th>Alcance candidato en casillas</th><th>Intención de distancia efectiva</th></tr></thead><tbody><tr><td>Daga</td><td>1</td><td>Fuerte de cerca; no puede simplemente golpear más lejos</td></tr><tr><td>Espada</td><td>Normalmente 1</td><td>Enfrentamiento cercano ordinario</td></tr><tr><td>Lanza</td><td>2</td><td>Ventaja de alcance solo con presentación acorde</td></tr><tr><td>Lanza larga / pica</td><td>2–3</td><td>Podría destacar a 3 y ser mala a 1</td></tr><tr><td>Acción de martillo grande / arma de asta</td><td>Puede afectar a 2</td><td>Depende de la acción real y su huella</td></tr><tr><td>Arco</td><td>Mayor, sin resolver</td><td>Modelo de proyectiles con factores compartidos de precisión</td></tr></tbody></table><p>Son ejemplos de prototipo, no distancias seleccionadas ni capacidades actuales del motor. La distancia mínima legal, la efectividad óptima y el alcance máximo no deben reducirse a un único número. Lunge, Sweep y Crushing Arc pueden modificar alcance mediante acciones físicamente creíbles. Athletics u otra habilidad no alarga mágicamente el equipo; puede desbloquear/mejorar esas técnicas.</p><h2 id="mechanical-and-visible-reach-must-agree" tabindex="-1">El alcance mecánico y el visible deben coincidir <a class="header-anchor" href="#mechanical-and-visible-reach-must-agree" aria-label="Enlace permanente a &quot;El alcance mecánico y el visible deben coincidir&quot;">​</a></h2><p>Una lanza que golpee a 2–3 casillas debe alcanzar visiblemente su objetivo mediante la animación/sprite/efecto elegido. Nada de golpes cuerpo a cuerpo a distancia invisible. Es un requisito de presentación junto a la autoridad del servidor, no permiso para que los píxeles del sprite decidan impactos o que la finalización de animaciones condicione resultados. Si los recursos actuales no pueden comunicar la acción, informar del conflicto de viabilidad antes de implementar; no alargar silenciosamente el alcance ni reescribir el diseño.</p><p>Orientación, LOS, movimiento del objetivo, colisión y perfiles corporales requieren reglas explícitas de acción. La extensión de arco/área es huella espacial, no automáticamente alcance máximo ni impactos múltiples garantizados. Contacto por objetivo, límites de área y reglas de fuego amigo siguen sin resolverse.</p><p>El <a href="/Syrolands-Public/es/game-design/combat/actions.html#canonical-action-schema">esquema de acciones</a> y las <a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html#archery-and-ranged-actions">reglas a distancia Legacy/Modern</a> definen ejecución y tiempos de proyectiles. No se seleccionan cambios de renderizado del cliente ni de red.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Alcance numérico de prueba de Batch 06 <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Enlace permanente a &quot;Alcance numérico de prueba de Batch 06&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">perfil de tres armas</a> asigna valores de prueba con estado Experimental a Longsword, Spear y War Hammer. Sus reglas de fases, recursos, cadencia, Flow, Familiarity marcial y preparación solo se aplican a esa prueba futura. Los ejemplos anteriores siguen siendo alternativas históricas fuera de este perfil; de ello no se deriva equilibrio definitivo, implementación de juego ni asignación numérica de hechizos.</p>',13)])])}const g=a(c,[["render",s]]);export{u as __pageData,g as default};
